// Must match the CONTACT_COUNTRIES order in src/pages/Contact.tsx.
const COUNTRY_NAMES = ["Lebanon","Saudi Arabia","Iraq","Ivory Coast","Nigeria","Rwanda","Cameroon","Zambia","Burkina Faso","Mali"];

const VIEW_W = 1600;
const VIEW_H = 760;
const ASPECT = VIEW_W / VIEW_H;
const FIXED_ZOOM = 3;

interface Base { width: number; height: number; }
interface View { x: number; y: number; }

interface ContactMapProps {
  hoveredCountry?: string | null;
}

export default function ContactMap({ hoveredCountry = null }: ContactMapProps) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const svgRef = useRef<HTMLDivElement | null>(null);
  const baseRef = useRef<Base>({ width: 0, height: 0 });
  const viewRef = useRef<View>({ x: 0, y: 0 });
  const pointers = useRef<Map<number, { x: number; y: number }>>(new Map());

  const applyTransform = useCallback(() => {
    const el = svgRef.current;
    if (!el) return;
    const { x, y } = viewRef.current;
    const b = baseRef.current;
    el.style.width = b.width * FIXED_ZOOM + 'px';
    el.style.height = b.height * FIXED_ZOOM + 'px';
    el.style.transform = `translate(${x}px, ${y}px)`;
  }, []);

  const clamp = useCallback((v: View): View => {
    const wrap = wrapRef.current;
    const b = baseRef.current;
    if (!wrap || !b.width) return v;
    const cw = wrap.clientWidth;
    const ch = wrap.clientHeight;
    const w = b.width * FIXED_ZOOM;
    const h = b.height * FIXED_ZOOM;
    const minX = Math.min(0, cw - w);
    const minY = Math.min(0, ch - h);
    const x = Math.min(0, Math.max(minX, v.x));
    const y = Math.min(0, Math.max(minY, v.y));
    return { x, y };
  }, []);

  const setView = useCallback((v: View) => {
    viewRef.current = clamp(v);
    applyTransform();
  }, [clamp, applyTransform]);

  const computeBase = useCallback(() => {
    const wrap = wrapRef.current;
    if (!wrap) return;
    const cw = wrap.clientWidth;
    const ch = wrap.clientHeight;
    let width: number, height: number;
    if (cw / ch < ASPECT) {
      height = ch;
      width = ch * ASPECT;
    } else {
      width = cw;
      height = cw / ASPECT;
    }
    baseRef.current = { width, height };
    const centeredX = Math.min(0, (cw - width * FIXED_ZOOM) / 2);
    const centeredY = Math.min(0, (ch - height * FIXED_ZOOM) / 2);
    setView({ x: centeredX, y: centeredY });
  }, [setView]);

  useEffect(() => {
    computeBase();
    const wrap = wrapRef.current;
    if (!wrap) return;
    const ro = new ResizeObserver(() => computeBase());
    ro.observe(wrap);
    return () => ro.disconnect();
  }, [computeBase]);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    (e.target as Element).setPointerCapture(e.pointerId);
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
  }, []);

  const onPointerMove = useCallback((e: React.PointerEvent) => {
    if (!pointers.current.has(e.pointerId)) return;
    const prev = pointers.current.get(e.pointerId)!;
    const dx = e.clientX - prev.x;
    const dy = e.clientY - prev.y;
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    const v = viewRef.current;
    setView({ x: v.x + dx, y: v.y + dy });
  }, [setView]);

  const endPointer = useCallback((e: React.PointerEvent) => {
    pointers.current.delete(e.pointerId);
  }, []);

  const { base, normalGold, strongGold } = useMemo(() => {
    const base: number[] = [];
    const normalGold: number[] = [];
    const strongGold: number[] = [];
    const hoveredIdx = hoveredCountry ? COUNTRY_NAMES.indexOf(hoveredCountry) : -1;
    for (let i = 0; i < DOTS.length; i += 3) {
      const c = DOTS[i + 2];
      if (c < 0) base.push(DOTS[i], DOTS[i + 1]);
      else if (c === hoveredIdx) strongGold.push(DOTS[i], DOTS[i + 1]);
      else normalGold.push(DOTS[i], DOTS[i + 1]);
    }
    return { base, normalGold, strongGold };
  }, [hoveredCountry]);

  return (
    <div
      ref={wrapRef}
      className="contact-map-canvas"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={endPointer}
      onPointerCancel={endPointer}
      onPointerLeave={endPointer}
      aria-label="World map highlighting countries served across Africa and the Middle East. Drag to pan."
    >
      <div ref={svgRef} className="contact-map-inner">
        <svg className="contact-map-svg" viewBox={`0 0 ${VIEW_W} ${VIEW_H}`} preserveAspectRatio="none">
          <g className="contact-map-base">
            {Array.from({ length: base.length / 2 }, (_, i) => (
              <circle key={'b' + i} cx={base[i * 2]} cy={base[i * 2 + 1]} r={0.85} />
            ))}
          </g>
          <g className="contact-map-gold">
            {Array.from({ length: normalGold.length / 2 }, (_, i) => (
              <circle key={'n' + i} cx={normalGold[i * 2]} cy={normalGold[i * 2 + 1]} r={0.85} />
            ))}
          </g>
          <g className="contact-map-gold-strong">
            {Array.from({ length: strongGold.length / 2 }, (_, i) => (
              <circle key={'s' + i} cx={strongGold[i * 2]} cy={strongGold[i * 2 + 1]} r={1.3} />
            ))}
          </g>
        </svg>
      </div>
    </div>
  );
}
